mapper.select:


    m.is_delete = 0
    AND m.tenant_id = #{tenantId}

        AND m.member_code like concat('%', #{memberCode}, '%')

    AND m.member_type = #{memberType}
    AND m.auth_status = #{authStatus}

        AND m.legal_subject_name like concat('%', #{legalSubjectName}, '%')


        AND m.nickname like concat('%', #{nickname}, '%')


        AND m.contact_name like concat('%', #{contactName}, '%')


        AND m.contact_phone like concat('%', #{contactPhone}, '%')

    AND m.vip_level = #{vipLevel}

        AND m.external_accept_enabled = #{externalAcceptEnabled}

    AND m.status = #{status}

order by m.create_time desc, m.member_id desc

where m.is_delete = 0 and m.member_id in
#{memberId}
order by m.member_id

select m.member_id, m.member_code, m.nickname, m.legal_subject_name, m.auth_status, m.status, m.create_time from `ry_rental`.`ry_rental_member` m where m.is_delete = 0
and m.member_code like concat('%', #{memberCode}, '%')
and m.nickname like concat('%', #{nickname}, '%')
and m.legal_subject_name like concat('%', #{legalSubjectName}, '%')
and m.member_type = #{memberType}
and m.auth_status = #{authStatus}
and m.status = #{status}
order by m.create_time desc, m.member_id desc
